"    text += BASE64[n >> 18 & 63] + BASE64[n >> 12 & 63] + (i + 1 < bytes.length ? BASE64[n >> 6 & 63] : \"=\") + (i + 2 < bytes.length ? BASE64[n & 63] : \"=\");",
"  }",
