"  for (let i = 0, value = 0, bits = 0, at = 0;i < digits.length; i++) {",
"    const digit = BASE64.indexOf(digits[i]);",
"    if (digit < 0)",
"      throw new Error(\"INVALID_BASE64\");",
"    value = (value << 6 | digit) & 65535;",
"    bits += 6;",
"    if (bits >= 8) {",
"      bits -= 8;",
"      bytes[at++] = value >> bits & 255;",
"    }",
"  }",
"  return bytes;",
"};",
