"      if (next === undefined)",
"        break;",
"      at = next;",
"    }",
"    return at.isRun ? own : at;",
"  };",
"  const listed = new Map;",
"  const list = (question, into) => {",
"    const note = \"note\" in question.source && typeof question.source.note === \"string\" ? plain3(question.source.note) : \"\";",
"    const id = JSON.stringify([question.agent, question.project, question.task, plain3(question.text), note, folderOf2(question.source.dir ?? \"\")]);",
"    const held = listed.get(id);",
"    if (held === undefined) {",
"      listed.set(id, { list: into, index: into.length });",
"      into.push(question);",
"    } else if (held.list === into && question.at > (held.list[held.index]?.at ?? 0))",
"      held.list[held.index] = question;",
"  };",
"  const pending = [];",
"  const older = [];",
"  const carded = new Set;",
"  for (const ask of model.asks) {",
"    list({ ...tag(ownerOf(ask), ask.project, ask.dir, ask.at), key: ask.key, task: ask.task, text: ask.text, stage: \"pending\", source: ask }, pending);",
"    carded.add(identity(ask.agent, ask.isOwn === true, ask.project, ask.task, ask.dir));",
"  }",
"  for (const turn of model.turns) {",
"    if (turn.isQuestion)",
"      list({ ...tag(ownerOf(turn), turn.project, turn.dir, turn.at), key: turn.key, task: \"\", text: turn.text, stage: \"pending\", source: turn }, pending);",
"  }",
"  const retained = [...model.reminder.map((item) => ({ item, stage: \"reminder\" })), ...model.older.map((item) => ({ item, stage: \"older\" }))];",
"  for (const { item, stage } of retained) {",
"    list({ ...tag(ownerOf(item), item.project, item.dir, item.at), key: item.key, task: item.task, text: item.text, stage, source: item }, older);",
"  }",
"  const finished = (model.finished ?? model.recent).filter((item) => item.isRun !== true && !(isKnown(item.at) && item.at < now - DONE_MS));",
"  const taken = new Set;",
"  for (const item of finished) {",
"    const found = rows.findIndex(({ row, shelf }, index) => shelf === \"stopped\" && row.isRun !== true && !taken.has(index) && (item.key !== undefined ? row.key === item.key : row.project === item.project && row.title === item.title && isHers(item, row)));",
"    if (found !== -1)",
"      taken.add(found);",
"  }",
"  const tasks = [];",
"  const stuck = [];",
"  const rowKeys = new Set;",
"  const rowIds = new Set(rows.filter(({ row }) => row.isRun !== true).map(({ row }) => identity(row.agent, row.isOwn === true, row.project, row.title, row.dir)));",
"  for (const [index, { row, shelf, isIdle }] of rows.entries()) {",
"    if (row.isRun === true || taken.has(index) || rowKeys.has(row.key))",
"      continue;",
"    rowKeys.add(row.key);",
"    const tagged = tag({ agent: row.agent, isOwn: row.isOwn === true }, row.project, row.dir, row.at);",
"    if (row.stuck !== undefined)",
"      stuck.push({ ...tagged, type: \"stuck\", key: `stuck:${row.key}`, task: row.title, reason: row.stuck.reason, source: row });",
"    tasks.push({ ...tagged, key: row.key, title: row.title, shelf, isIdle, hasCard: row.stuck !== undefined || carded.has(identity(row.agent, row.isOwn === true, row.project, row.title, row.dir)), source: row });",
"  }",
"  const waiting = new Map;",
"  for (const ask of model.asks) {",
"    const id = identity(ask.agent, ask.isOwn === true, ask.project, ask.task, ask.dir);",
"    if (ask.isRun === true || rowIds.has(id))",
"      continue;",
"    const held = waiting.get(id);",
"    if (held === undefined)",
