"  }",
"  for (const [id, { ask, at }] of waiting) {",
"    const tagged = tag({ agent: ask.agent, isOwn: ask.isOwn === true }, ask.project, ask.dir, at);",
"    tasks.push({ ...tagged, key: `waiting:${id}`, title: ask.task, shelf: \"open\", isIdle: false, hasCard: true, source: ask });",
"  }",
"  const repeats = new Map;",
"  const usedKeys = new Set;",
"  for (const item of finished) {",
"    const base = `done::${item.project}::${item.title}`;",
"    let key = item.key;",
"    if (key === undefined) {",
"      let repeat = repeats.get(base) ?? 0;",
"      key = repeat === 0 && !usedKeys.has(base) ? base : `${base}#${Math.max(2, repeat + 1)}`;",
"      while (usedKeys.has(key)) {",
"        repeat = Math.max(repeat + 1, Number(key.slice(key.lastIndexOf(\"#\") + 1)) || 0) + 1;",
"        key = `${base}#${repeat}`;",
"      }",
"      repeats.set(base, repeat || 1);",
"    }",
"    usedKeys.add(key);",
"    const tagged = item.isOwn === true || item.agent !== undefined ? tag({ agent: item.agent ?? \"\", isOwn: item.isOwn === true }, item.project, item.dir, item.at) : { agent: \"\", isOwn: false, project: item.project, repo: repoName(item.project, item.dir), at: timeOf(item.at) };",
"    tasks.push({",
"      ...tagged,",
"      key,",
"      title: item.title,",
"      shelf: \"done\",",
"      isIdle: false,",
"      hasCard: false,",
"      source: item",
"    });",
"  }",
"  const unreadable = new Set;",
"  for (const one of model.agents ?? [])",
"    if (one.unreadable === true)",
"      unreadable.add(note(one.agent));",
"  const sortedTasks = newestFirst(tasks);",
"  const cards = newestFirst([...pending.map((question) => ({ ...question, type: \"question\" })), ...stuck]);",
"  const sortedOlder = newestFirst(older);",
"  const bucketOf = (pick) => {",
"    const here = sortedTasks.filter(pick);",
"    const open = here.filter((task) => task.shelf === \"open\");",
"    const stopped = here.filter((task) => task.shelf === \"stopped\");",
"    const done = here.filter((task) => task.shelf === \"done\");",
"    const asking = cards.filter(pick);",
"    const back = sortedOlder.filter(pick);",
"    return {",
"      counts: { open: open.length, needs: asking.length, stopped: stopped.length, done: done.length, older: back.length },",
"      cards: asking,",
"      open: open.filter((task) => !task.hasCard),",
"      stopped,",
"      done,",
"      older: back",
"    };",
"  };",
"  const lastOf = new Map;",
"  for (const one of [...sortedTasks, ...cards, ...sortedOlder])",
"    if (!one.isOwn && one.agent !== \"\")",
"      lastOf.set(one.agent, Math.max(lastOf.get(one.agent) ?? 0, one.at));",
"  const agents = [...spelled.keys()].map((agent, index) => ({ agent, index, last: lastOf.get(agent) ?? 0 })).sort((a, b) => b.last - a.last || a.index - b.index).map(({ agent, last }) => ({",
"    ...bucketOf((one) => !one.isOwn && one.agent === agent),",
"    agent,",
"    name: agentLabel(spelled.get(agent) ?? agent, s),",
"    icon: iconOf(agent),",
"    last,",
"    isUnreadable: unreadable.has(agent)",
"  }));",
"  const projects = new Map;",
"  const touch = (one) => {",
"    const held = projects.get(one.repo) ?? { name: one.repo, open: 0, at: 0 };",
"    held.at = Math.max(held.at, one.at);",
"    projects.set(one.repo, held);",
"    return held;",
"  };",
"  for (const task of sortedTasks)",
"    if (task.shelf === \"open\")",
"      touch(task).open += 1;",
"  for (const one of [...cards, ...sortedOlder])",
"    touch(one);",
"  return {",
"    agents,",
"    needs: {",
"      n: cards.length,",
"      questions: cards.filter((card) => card.type === \"question\").length,",
"      stuck: cards.filter((card) => card.type === \"stuck\").length,",
"      cards,",
"      older: sortedOlder",
"    },",
"    working: sortedTasks.filter((task) => {",
"      if (task.shelf !== \"open\" || task.hasCard || task.isOwn)",
"        return false;",
"      const source = task.source;",
"      const isDoing = typeof source === \"object\" && source !== null && \"steps\" in source && Array.isArray(source.steps) && source.steps.some((step) => step.status === \"doing\");",
"      return isDoing || task.at > 0 && now - task.at <= WORKING_MS2;",
"    }),",
"    quiet: quietOf(cards, sortedTasks, now),",
"    all: { ...bucketOf((one) => !one.isOwn), isHidden: agents.length < 2 },",
"    own: bucketOf((one) => one.isOwn),",
"    projects: newestFirst([...projects.values()]).map(({ name, open }) => ({ name, open }))",
"  };",
"};",
