"var ASK_KINDS = [\"confirm\", \"choose\", \"input\", \"do\", \"review\", \"wait\", \"reply\"];",
"var CHOICE = /(.+?)\\s*(?:還是|还是|或是|\\bor\\b)\\s*(.+?)[？?]/i;",
