"var questionWords2 = (text) => {",
"  let question = text.trim();",
"  const pairs = { '\"': '\"', \"'\": \"'\", \"“\": \"”\", \"「\": \"」\", \"『\": \"』\", \"(\": \")\" };",
"  while (question.length >= 2 && pairs[question[0]] === question[question.length - 1]) {",
"    const open = question[0];",
"    const close = pairs[open];",
