"var optionsOf = (text) => {",
"  if (!CHOICE_MARKER.test(text))",
"    return [];",
"  const match = CHOICE.exec(text);",
"  if (match === null)",
"    return [];",
"  const clauses = (match[1] ?? \"\").split(/[，,：:；;。]/).map((one) => one.trim()).filter((one) => one !== \"\");",
